import{_ as e,o as i,c as o,a6 as n}from"./chunks/framework.DNkVJs23.js";const k=JSON.parse('{"title":"Pytania i odpowiedzi","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/pl/faq/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/pl/faq/"}],["meta",{"property":"og:title","content":"Pytania i odpowiedzi | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Dane Monster Hunter i wyszukiwanie zestawów do Wilds, Rise z Sunbreak oraz World z Iceborne."}]]},"headers":[],"relativePath":"pl/faq/index.md","filePath":"pl/faq/index.md"}'),r={name:"pl/faq/index.md"};function t(l,a,p,s,d,c){return i(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="pytania-i-odpowiedzi" tabindex="-1">Pytania i odpowiedzi <a class="header-anchor" href="#pytania-i-odpowiedzi" aria-label="Permalink to &quot;Pytania i odpowiedzi&quot;">​</a></h1><h2 id="jakie-gry-sa-obsługiwane" tabindex="-1">Jakie gry są obsługiwane? <a class="header-anchor" href="#jakie-gry-sa-obsługiwane" aria-label="Permalink to &quot;Jakie gry są obsługiwane?&quot;">​</a></h2><p>Obsługiwane są Wilds, Rise z Sunbreak oraz World z Iceborne. Dane i mechaniki każdej gry pozostają oddzielne; grę wybiera się na ekranie głównym.</p><h2 id="gdzie-pobrac-aplikacje" tabindex="-1">Gdzie pobrać aplikację? <a class="header-anchor" href="#gdzie-pobrac-aplikacje" aria-label="Permalink to &quot;Gdzie pobrać aplikację?&quot;">​</a></h2><p>Android jest dostępny w <a href="https://play.google.com/store/apps/details?id=com.eurekaffeine.mhd" target="_blank" rel="noreferrer">Google Play</a>, a HarmonyOS w <a href="https://appgallery.huawei.com/app/detail?id=com.eurekaffeine.monsterhunterdex&amp;channelId=SHARE&amp;source=appshare" target="_blank" rel="noreferrer">AppGallery</a>. Wersja iOS jest przygotowywana. Zobacz <a href="./../#download">pobieranie</a>; dostępność zależy od regionu i urządzenia.</p><h2 id="czy-aplikacja-działa-offline" tabindex="-1">Czy aplikacja działa offline? <a class="header-anchor" href="#czy-aplikacja-działa-offline" aria-label="Permalink to &quot;Czy aplikacja działa offline?&quot;">​</a></h2><p>Dane są dołączone do aplikacji. Przeglądanie, wyszukiwanie, ulubione i dobieranie pancerza działają lokalnie. Zewnętrzne strony i aktualizacje wymagają połączenia.</p><h2 id="jak-działa-wyszukiwanie-pancerza" tabindex="-1">Jak działa wyszukiwanie pancerza? <a class="header-anchor" href="#jak-działa-wyszukiwanie-pancerza" aria-label="Permalink to &quot;Jak działa wyszukiwanie pancerza?&quot;">​</a></h2><p>Określ umiejętności i poziomy, zablokuj lub wyklucz elementy oraz uwzględnij posiadane dekoracje. Rise obsługuje również własne talizmany i ulepszone pancerze. Wyniki zależą od danych i warunków; funkcja nie oblicza obrażeń.</p><h2 id="jakie-jezyki-sa-dostepne" tabindex="-1">Jakie języki są dostępne? <a class="header-anchor" href="#jakie-jezyki-sa-dostepne" aria-label="Permalink to &quot;Jakie języki są dostępne?&quot;">​</a></h2><p>Aplikacja oferuje 14 języków. Niektóre teksty z gry mogą być wyświetlane po angielsku. Brakujące teksty hiszpańskie z Ameryki Łacińskiej zastępowane są najpierw hiszpańskim z Hiszpanii, a następnie angielskim.</p><p>English · 日本語 · 简体中文 · 繁體中文 · Français · Deutsch · Italiano · 한국어 · Español (España) · Español (Latinoamérica) · Português (Brasil) · Polski · Русский · العربية</p><h2 id="czy-to-oficjalna-aplikacja" tabindex="-1">Czy to oficjalna aplikacja? <a class="header-anchor" href="#czy-to-oficjalna-aplikacja" aria-label="Permalink to &quot;Czy to oficjalna aplikacja?&quot;">​</a></h2><p>Nie. To niezależna aplikacja fanowska, niepowiązana z CAPCOM ani przez nią zatwierdzona. Grafiki i dane Monster Hunter należą do CAPCOM Co., Ltd.</p>',14)])])}const u=e(r,[["render",t]]);export{k as __pageData,u as default};
